import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import styles from './styles';
import {getListStyle} from './helper';
import {isEmpty} from 'lodash';
import GroupRadio, {
  GroupData,
} from '../../../../../../../../../components/GroupRadio';
import TextCM from '../../../../../../../../../components/Text';
import {IconBlackDown} from '../../../../../../../../../assets/images';
import BottomSheetCM from '../../../../../../../../../components/BottomSheet';

type Props = {
  value?: GroupData;
  onPicStatus: (value: GroupData | undefined) => void;
  fullName: string;
};

const PicFontView = ({value, onPicStatus, fullName}: Props) => {
  const {t} = useTranslation();

  const [isVisible, setIsVisible] = useState<boolean>(false);

  const togglePicType = () => {
    setIsVisible(!isVisible);
  };

  return (
    <>
      <TouchableOpacity
        style={[
          styles.btnPicType,
          isEmpty(fullName) && {
            backgroundColor: '#EAECF0',
          },
        ]}
        onPress={togglePicType}
        disabled={isEmpty(fullName)}>
        {value ? (
          <View
            style={{
              flex: 1,
            }}>
            <TextCM style={styles.txtLabel}>{t('NT.TxtChangeStyle')}</TextCM>
            <TextCM
              numberOfLines={1}
              style={[
                styles.txtType,
                value && {
                  fontFamily: value.id as string,
                },
              ]}>
              {fullName}
            </TextCM>
          </View>
        ) : (
          <TextCM style={styles.txtNoType}>{t('NT.TxtChangeStyle')}</TextCM>
        )}
        <IconBlackDown width={16} height={16} />
      </TouchableOpacity>
      <BottomSheetCM
        renderContent={
          <ContentPicTypeView
            value={value}
            onPicType={type => {
              onPicStatus(type);
              togglePicType();
            }}
            fullName={fullName}
          />
        }
        title={t('NT.TxtChangeStyle')}
        onClose={togglePicType}
        isVisible={isVisible}
      />
    </>
  );
};

type ContentPicTypeViewProps = {
  value?: GroupData;
  onPicType: (value: GroupData | undefined) => void;
  fullName: string;
};

const ContentPicTypeView = ({
  value,
  onPicType,
  fullName,
}: ContentPicTypeViewProps) => {
  const {t} = useTranslation();

  const renderLabel = (value: GroupData) => {
    return (
      <TextCM
        style={{
          fontFamily: value.id as string,
        }}>
        {fullName}
      </TextCM>
    );
  };

  return (
    <View style={styles.viewPicType}>
      <TextCM style={styles.txtTitlePicType}>{t('NT.TxtPicStyleSign')}</TextCM>
      <GroupRadio
        data={getListStyle() as GroupData[]}
        onPressData={onPicType}
        currentValue={value as GroupData}
        containerStyle={styles.viewGroupRadio}
        renderLabel={renderLabel}
      />
    </View>
  );
};

export default PicFontView;
